import assert from "node:assert/strict";
import {readFileSync} from "node:fs";

const read=path=>readFileSync(new URL("../"+path,import.meta.url),"utf8");
const registry=JSON.parse(read("data/geography/research/exact-sacred-subject-photo-inventory-20261031.v1.json"));
const html=read("tools/precise-sacred-subject-photo-finder.html");
const geography=JSON.parse(read("data/geography/seed-registry.v1.json"));
const phenomena=JSON.parse(read("data/explore/sacred-phenomena-seed.v1.json"));
const shrineInventory=JSON.parse(read("data/shrines/editorial-master-inventory-20261021.v1.json"));
const ids=arr=>new Set(arr.map(x=>x.subject_id));
const places=new Set(geography.places.map(x=>x.place_id));
const relicIDs=new Set(phenomena.relics.map(x=>x.id));
const apparitionIDs=new Set(phenomena.apparitions.map(x=>x.id));
assert.equal(registry.schema,"AO_EXACT_PHYSICAL_SACRED_SUBJECT_RESEARCH_V1");
assert.equal(registry.publication,"RESEARCH_ONLY_NO_IMAGES_APPROVED");
assert.equal(registry.sites.length,geography.places.length);
assert.equal(new Set(registry.sites.map(x=>x.place_id)).size,registry.sites.length);
assert.equal(ids(registry.subjects).size,registry.subjects.length);
assert(registry.subjects.every(x=>places.has(x.place_id)),"Every subject has an existing physical Place owner");
const guideStops=registry.subjects.filter(x=>x.subject_type==="SOURCE_DESCRIBED_PILGRIMAGE_STOP");
const relics=registry.subjects.filter(x=>x.subject_type==="SOURCE_ATTESTED_RELIC_IDENTITY");
const apparitionContexts=registry.subjects.filter(x=>x.subject_type==="APPARITION_ACCOUNT_CONTEXT_NOT_PHOTOGRAPHABLE_EVENT");
const focus=registry.subjects.filter(x=>x.photo_search_state==="PRECISE_QUERY_READY_PHOTO_REVIEW_REQUIRED");
assert.equal(guideStops.length,88);
assert.equal(relics.length,phenomena.relics.length);
assert.equal(apparitionContexts.length,phenomena.apparitions.length);
assert(focus.length>=20,"At least the source-audited pilot has precise photo targets");
assert.equal(relics.filter(x=>relicIDs.has(x.canonical_relic_id)).length,relics.length);
assert.equal(apparitionContexts.filter(x=>apparitionIDs.has(x.canonical_apparition_id)).length,apparitionContexts.length);
assert(guideStops.every(x=>x.photo_search_state==="REQUIRES_EXACT_SUBJECT_ADJUDICATION"));
assert(apparitionContexts.every(x=>x.photo_search_state==="NO_GENERIC_APPARITION_IMAGE_SEARCH"));
assert(focus.every(x=>x.search_queries.length&&x.evidence_urls.length&&x.search_queries.every(y=>y.length>=18)));
assert(focus.every(x=>x.media_publishable===false&&x.image_status==="NOT_APPROVED_NO_PUBLISHED_IMAGE"));
assert(registry.subjects.every(x=>x.media_publishable===false),"Research references cannot become published images");
assert(focus.every(x=>!Object.hasOwn(x,"geo")),"Subsite subjects cannot mint coordinates/pins");
assert.equal(registry.count_summary.marian_shrine_records,shrineInventory.shrines.filter(x=>x.category==="MARIAN").length);
assert.equal(registry.count_summary.marian_sites_without_curated_exact_target,
 registry.sites.filter(x=>x.marian_subject_action==="IDENTIFY_ORIGINAL_MARIAN_SUBJECT").length);
const find=id=>focus.find(s=>s.subject_id==="subject:focus:"+id);
assert(find("knock-original-gable")&&find("knock-lorenzo-ferri-marble"));
assert.notEqual(find("knock-original-gable").subject_type,find("knock-lorenzo-ferri-marble").subject_type);
assert.match(find("knock-lorenzo-ferri-marble").rights_gate,/MODERN_SCULPTURE/);
assert.match(find("knock-basilica-mosaic").rights_gate,/MODERN_ARTWORK/);
assert(find("lourdes-massabielle-grotto")&&find("nevers-massabielle-replica"));
assert.notEqual(find("lourdes-massabielle-grotto").place_id,find("nevers-massabielle-replica").place_id);
assert.equal(find("nevers-massabielle-replica").subject_type,"DOCUMENTED_REPLICA");
assert.equal(find("padua-st-anthony-tongue").canonical_relic_id,"relic:IT:anthony-padua-tongue");
assert.equal(find("padua-st-anthony-jawbone").canonical_relic_id,"relic:IT:anthony-padua-jawbone");
assert.notEqual(find("padua-st-anthony-tongue").subject_id,find("padua-st-anthony-jawbone").subject_id);
const embedded=html.match(/const REGISTRY = ([^\n]*);/);
assert(embedded&&JSON.parse(embedded[1]).schema===registry.schema,"Standalone finder must embed research inventory");
const current=JSON.parse(embedded[1]);
assert.deepEqual(current.count_summary,registry.count_summary,"Standalone inventory must exactly match canonical review file");
const script=html.match(/<script>([\s\S]*?)<\/script>/);
assert(script,"Standalone reader needs a script");
new Function(script[1]);
assert(script[1].includes("gsrnamespace:\"6\""),"Commons file namespace constraint required");
assert(script[1].includes("if(!ready(s))"),"Site-only and broad relic searches must remain disabled");
assert(script[1].includes("identity_verified:false"),"Export must not preapprove identities");
assert(script[1].includes("rights_verified:false"),"Export must not preapprove licenses");
assert(script[1].includes("original_bytes_verified:false"),"Export must not preapprove file bytes");
assert(script[1].includes("mode===\"marianMissing\""),"Missing Marian subjects must have their own work queue");
assert(script[1].includes("new Map(existing.map"),"Import must preserve previously selected photographs");
console.log("Exact Sacred Subjects photo finder: 530 Place IDs, 88 stops, 127 relics, 33 apparitions, "+
 focus.length+" source-attested exact targets; safe gated search and candidate exports PASS");
